# -*- coding: utf-8 -*-
"""LLM RL 指南 编译 build"""
import json, os, sys

DATA = {'title': '为 LLM 做强化学习：从基础到前沿的完整指南', 'lead': ['RL 在 LLM 研究史上一直扮演关键角色：造出早期指令跟随模型、推进对齐与安全、让 LLM 解复杂推理题。但 RL 仍是 AI 研究里演进最快的领域之一。这篇单篇指南从第一性原理爬升到 RL 研究前沿：覆盖 RL 基础、当前用于训练 LLM 的策略梯度算法的完整演化、以及几个新兴研究领域。'], 'summary': [{'key': '统一结构', 'body': 'LLM RL 算法都是「log 概率梯度 × 学习信号」，差异在 ψ 与更新约束。'}, {'key': '算法路线', 'body': 'VPG → REINFORCE(baseline) → PPO(actor-critic+clip) → GRPO(去 critic、组内相对优势) → GSPO/DAPO/Dr.GRPO/TIS/CISPO。'}, {'key': 'PPO vs GRPO', 'body': 'PPO 训 critic(4 模型)省内存换来复杂；GRPO 去 critic 但多采样 completion。细节（loss 聚合/归一化/clip 边界/引擎 mismatch）决定 scale 稳定性。'}], 'sections': [{'type': 'h2', 'title': 'RL 基础：框架与目标', 'paras': ['RL 训练里我们有一个 **agent** 在某种 **环境** 里迭代取 **动作**。每一步用一个时间步 t 标记，t 时刻的动作记为 a(t)。动作由 **策略**（可用作 agent 的大脑）预测，参数为 θ（训练 LLM 时策略就是 LLM 本身）。策略可确定或随机，对 LLM 我们假设随机——随机策略 π(θ) 输出可能动作集上的概率分布、动作 a(t) 从这里采样。', '策略输出动作后，环境的状态按 **transition function**（环境的一部分）更新，状态记为 s(t)。动作后环境给奖励 r(t)（可正可负可零）刻画状态/动作的期望度。RL 本质是试错：agent 在环境中行动，训练过程通过奖励强化（正或负）被观察行为——故名「reinforcement」learning。', '从初始状态 s(0) 开始，agent 重复：采样动作 → 转到新状态 → 获奖励，直到终态 s(T)（因是终态或达最大步数）。这些步骤的序列构成 **trajectory（轨迹）**。RL 反复从 agent 采样轨迹，让它探索状态-动作空间、最终发现高奖励行为模式。', '轨迹概率 = 动作分布 π(θ)(a(t)|s(t)) 和状态转移 P(s(t+1)|a(t),s(t)) 的链式乘积。**累计回报（return）**= 轨迹所有 r(t) 的和，可带折扣因子 γ（∈[0,1]）指数衰减未来奖励、鼓励模型尽早获得奖励。对 LLM post-training 常有限 T 且 γ=1（主要用轨迹/完成级别的奖励而非逐状态）。', '**RL 目标**：最大化当前策略的期望回报。实践中枚举所有轨迹不可行，用 **Monte Carlo 估计**（对随机采样轨迹的回报取均值）。'], 'fig_after': {'0': [{'src': 'fig01.png', 'caption': '图 1：RL 基础问题设定——agent、action、环境、reward。'}]}}, {'type': 'h2', 'title': '价值与优势函数', 'paras': ['**价值函数** V(s)：从状态 s 按当前策略 π(θ) 行动得到的期望累计回报。**动作价值 / Q 函数** Q(s,a)：从 s 取动作 a 后按策略的期望累计回报。**优势函数** A(s,a)=Q(s,a)-V(s)：动作 a 相对策略在当前状态 s 的期望表现的相对优劣。优势为正 = 取 a 后期望回报比该状态的期望高，反之亦然。', '直觉：RL 里我们不总需要绝对描述一个动作多好，而只需它比其它平均好多少——这就是优势函数。价值、动作价值、优势函数作为期望通常无法精确算，需用当前策略采样的真实轨迹信息估计。观测回报 G(t) 是 Q(s(t),a(t)) 的 Monte Carlo 估计；价值函数 V(s(t)) 需用 OPE 或 critic 估计。'], 'fig_after': {'0': [{'src': 'fig02.png', 'caption': '图 2：价值函数与优势函数定义。'}, {'src': 'fig03.png', 'caption': '图 3：RL 目标——期望回报。'}]}}, {'type': 'h2', 'title': '为 LLM 制定 RL + KL 正则', 'paras': ['**为 LLM 制定 RL**：LLM 自回归生成 token。一个常见公式是 **bandit（完成级）**：整段 completion 视为一个动作、获得单一 outcome reward（由奖励模型评分）。替代是 token 级 MDP：每 token 是一个状态/动作。两种都是常用设定（outcome-reward 因简单常用），RL 目标常用带 KL 正则的形式。', '**KL 散度**：RL 的目标是最大化期望回报，但为使模型不偏离初始行为过远（维持流畅度/语义），在 reward 上加 KL 惩罚——鼓励新策略接近某参照策略。KL 正则策略通常是参照模型（RL 开始前的 checkpoint）或旧策略（采样数据的策略）。KL 惩罚对生成模型尤其重要，防止过度优化单一奖励导致的模式坍塌。', '**重要性采样**：评估策略 π(θ) 的目标时用旧策略 π_old 采样的 rollout，通过重要性比 π(θ)(a|s)/π_old(a|s) 校正概率差异。这是 PPO/GRPO 等几乎所有现代 LLM RL 算法的基础组块。'], 'fig_after': {}}, {'type': 'h2', 'title': 'Vanilla Policy Gradient (VPG)', 'paras': ['策略梯度算法计算 RL 目标对策略参数的梯度——**策略梯度**。该梯度有两部分：① 动作 a(t) 对数概率对 θ 的梯度（参数空间中增加 a(t) 似然的方向）；② 标量 ψ_t（per-action 分数）基于动作质量控制梯度的大小和方向——坏动作给大负值降其概率、中性动作给接近 0。', 'VPG 推导用两条恒等式：连续的期望定义、log-derivative trick（∇_θ log p_θ(x) = p_θ(x)·∇_θ log p_θ(x)）。结果是**动作级对数概率梯度按回报/优势信号加权之和**——这一结构出现在本文几乎每个策略梯度算法里。', '**VPG 实现**：用完成级 bandit 公式，整段 completion 视为一个动作得单一 outcome reward。把每 token 的对数概率求和得 sequence 级对数概率，乘 completion 级回报得 VPG loss（取负因 PyTorch 默认梯度下降）。现代算法（PPO/GRPO）很多是 loss 而非梯度表达式。', '**降方差**：VPG 问题①梯度高方差（用相对小的 rollout 集估计回报）、②对大而不稳定更新无保护。大多数策略梯度算法通过降方差或对更新设 trust region 解决。'], 'fig_after': {'0': [{'src': 'fig04.png', 'caption': '图 4：策略梯度结构——log 概率梯度 × 学习信号。'}]}}, {'type': 'h2', 'title': 'REINFORCE：baseline 降方差', 'paras': ['REINFORCE 是 VPG 的 Monte Carlo 实例：采样 rollout、对策略梯度表达式取平均。高方差可通过**动作无关的 baseline**（如平均回报）从采样回报中减去来降。LLM 设 outcome-reward 时 baseline = 平均 reward。', '给策略梯度加 baseline 不引入偏置（EGLP lemma 保证：baseline 不依赖动作 a(t) 时 E[b(s(t))·∇logπ]=0）。注：batch mean 若含当前 completion，则不是动作无关（每样本贡献到它自己 baseline）→ 引入轻微偏置。', '**RLOO** 恰好修这个问题：从 baseline 中**排除当前 completion 自身**的 reward，保留动作无关性质。之后看到 GRPO 也用这思路（组内多 completion 对比）。'], 'fig_after': {}}, {'type': 'h2', 'title': 'PPO：actor-critic + clipping', 'paras': ['REINFORCE 的 Monte Carlo 高方差导致训练不稳。用更有信息量的 baseline——**价值函数** V(s(t))——得到优势估计 A(s(t),a(t))=G(t)-V(s(t))。这自然引出 **actor-critic** 框架：同时训练策略（actor）和值模型（critic）。critic 用 LLM backbone + 标量 value head，预测每个 token 位置的期望未来回报。价值函数是 on-policy 的（依赖策略当前参数）须持续更新，通常用预测值与观测回报的回归损失训练。', '**TRPO**（PPO 前身）：把目标设成带硬约束的 surrogate objective（期望 KL 发散 < δ），理论上单调改进策略。但约束目标难优化（需二阶近似、共轭梯度、线搜索）。', '**PPO** 是更简单的替代：去掉 KL 硬约束、保留近似目标，但引入 **clipping** 惩罚把策略比限制在 [1-ε, 1+ε]。PPO 目标 = 最小(clipped, unclipped)——对未裁剪目标是悲观下界。Clipping 只在目标会改进过于激进时生效（单向），防止策略比把目标无限推高，鼓励保守更新。', '**PPO 里的多个策略**：旧策略 π_old（生成当前 batch rollout，重要性比用它）频繁刷新；参照策略 π_ref（RL 全程冻结、KL 正则用）。二者协同：重要性比校正旧 rollout 与当前策略的不匹配、相对 π_ref 的 KL 抑制过度漂移。', 'PPO 实现采用 token 级 MDP：每 token 单独计算 return 和 advantage。关键组件：① 采样 KL 惩罚（rollout 策略 vs 参照模型）直接从 per-token reward 减去，rollout 时算一次、多次 PPO update 中保持固定；② 学到 critic 算 advantage 并 MSE 训练；③ 策略比相对 old model、同 rollout 做多次更新（num_ppo_epochs）；④ clipped PPO loss；⑤ batch 聚合方式对性能有不可忽视影响。数值技巧：用 log 概率而非原始概率比。'], 'fig_after': {'0': [{'src': 'fig05.png', 'caption': '图 5：actor-critic 框架高层示意。'}]}}, {'type': 'h2', 'title': 'GAE 与 RL 内存开销', 'paras': ['**GAE（广义优势估计）**：上述简单优势=return 减预测价值。实践中大多用 GAE。基于 TD residual 的单步优势（V(s(t)) vs r(t)+V(s(t+1))）偏差高。GAE 用所有 N 步优势估计的指数加权组合，权重 λ∈[0,1] 控偏差-方差权衡（常用 λ=0.95；训练不稳时降 λ 得低方差更新）。', '**RL 内存开销**：PPO 训策略 + critic 两个模型，还要跑参照策略和奖励模型——最多管理 4 个模型、其中 2 个在训练。半精度推理每 1B 参数约 2GB（Qwen-3-32B 全上下文 131K 会从 ~70GB 涨到 ~400GB）；训练每 1B 参数约 16GB（含优化器状态和梯度）。backprop 需 cache 前向激活、反向梯度、Adam 梯度历史——可到推理的 12× 内存。GRPO 因不训 critic（只训一个模型）大幅省内存。'], 'fig_after': {'0': [{'src': 'fig06.png', 'caption': '图 6：训练 vs 推理的内存消耗对比。'}]}}, {'type': 'h2', 'title': 'GRPO：去掉 critic，组内相对优势', 'paras': ['PPO 实际缺点：需训值模型（critic）增加内存、计算、复杂度。**GRPO** 提出更简单的优势估计：为每个 prompt 采样多个 completion（一组），用这些 completion 的 reward 构造 baseline——组内相对优势。', '**优势估计**：completion i 的优势 = (r(i) - 组平均 reward) / 组 reward 标准差。这与 RLOO 类似均为免值函数、对比同 prompt 的多 completion；Dr.GRPO 变体可证与 RLOO 的优势估计差常数缩放。因优势完全从组内 reward 估计，每 prompt 常需采样较多样本（PPO/REINFORCE 可 1 样本，GRPO 需多样本稳梯度）。', '**Surrogate loss**：GRPO 用与 PPO 几乎相同的 surrogate loss（同重要性比、PPO 式 clipping、多 update）。区别：KL 罚直接进（可微）loss 而非 reward——GRPO 优化中重算 KL、梯度可流经它；PPO 是在 reward 里采样 KL、detach 保持固定。', '**内存**：GRPO 不训 critic（只训一个模型 vs PPO 两个），省计算并大幅省内存——消除一个可训练模型比移除只推理的模型（reward/ref）影响大得多。', 'GRPO 实现：每 prompt 采样 G 个 completion，组内 reward 归一化（(r-mean)/std）得 advantage，token 级 objective 广播 sequence 优势到所有 token，做多次 GRPO update。也支持 process reward（按组内所有 process reward 归一化、每 token 优势=后续步骤 reward-to-go）。'], 'fig_after': {'0': [{'src': 'fig07.png', 'caption': '图 7：GRPO 组内优势估计（来自 GRPO 原论文）。'}]}}, {'type': 'h2', 'title': 'GRPO++：让 RL 真正有效的技巧', 'paras': ['DeepSeek-R1 后 GRPO 爆火，但复现训练管线不平凡，催生大量修改。', '**GSPO（序列级比）**：GRPO 目标有 misalignment——advantage 在 sequence 级、策略比/loss 在 token 级。per-token 比在长序列/大稀疏 MoE 中高方差、单 token 可主导 loss。GSPO 用序列级重要性比（log 几何均值、按序列长归一化），稳定训练、提升采样效率和性能，被 Qwen3 采用。', '**DAPO（训练配方）**：解决 vanilla GRPO 的熵坍塌（高概率 token 被强调、低概率探索 token 被罚）。decoupled clip 用 [1-ε下限, 1+ε上限]（ε下限0.2、ε上限0.28）——提高 ε上限 防熵坍塌。动态采样过滤全同 reward 的 prompt 组、继续采样到 batch 满。token 级 loss 平均防序列长偏置；overlong filtering 去掉被截断响应的不稳定 reward、加长度惩罚。', '**Dr. GRPO**：指出 GRPO 两偏置。① response 级长度偏置——GRPO 按序列 token 数归一化 loss，按固定常数 MAX_TOKENS 归一化可去掉长度影响；② 问题级难度偏置——advantage 分母标准差让太易/太难问题的 advantage 过大，去掉标准差项修复。提升稳定性、token 效率。', '**TIS（截断重要性采样）**：现代 RL 用分离引擎（vLLM/SGLang 采样 rollout + FSDP/DeepSpeed 算更新），引擎间 token 概率不一致无法简单标准化。TIS 在策略梯度里加引擎间重要性比校正 mismatch。与 PPO 比的重要区别：直接截断比（min(r(t),ρ) 单侧上界）而非两段最小。token 级 TIS 常用、但 token 级比引入偏置，sequence 级方差高——bias-variance 权衡。被 verl、OpenInstruct 采用。', '**CISPO**：注意力里重要的「fork」token（如「aha」「wait」）初始概率低、首个更新后概率暴涨 → PPO 会 clip 掉它们从后续 off-policy 更新消失。MiniMax-M1 每 batch 16 次更新，关键 token 被遮掉严重伤效率。CISPO 用 REINFORCE 式 loss + stop-gradient 到 clipped 比：比作为权重控 token 贡献、而非 clip 后置零——所有 token 都贡献梯度。'], 'fig_after': {}}, {'type': 'h2', 'title': '高级研究主题', 'paras': ['**Online vs Offline**：在线（PPO/GRPO 持续生成 on-policy completion）vs 离线（DPO 固定数据集）。在线更难编排，但研究一致显示 on-policy 数据对性能有积极影响——尤其在困难设定里高奖励响应初始不易出现时需要主动探索。semi-online（周期刷新 on-policy 样本）可恢复部分收益；异步基础设施须处理部分 off-policy 的 stale 数据。新鲜 on-policy 数据是 RL 结果好的关键。', '**Continual Learning**：历史上面临灾难性遗忘。但 on-policy RL 天然对遗忘鲁棒——训练用模型自身采样的 on-policy data，更新贴近当前模型已合理的行为，策略分布偏移小（KL 测），与遗忘强相关。SFT 学新任务好但渐进忘旧。Nemotron-Cascade 用序列 RL 管线。', '**Rubric-based rewards**：可验证领域（math/code 用确定性 verifier）适合 RL，但开放任务（创意写作/科研）不可验证。rubric 奖励：先派生出 prompt 特定的质量标准 checklist，用 LLM judge 逐条评估并聚合。对开放任务提供 informative、可控的奖励信号、降 reward hacking 风险。', '**RL Scaling Laws**：RL 性能确实随 compute 可预测扩展，但比预训练 messy——用下游 reward/accuracy 度量、应用特定、依赖评估设置；RL compute 分 rollout 生成和策略更新两半难一致测。有用发现：早期阶段可外推到更大规模预测表现、测试配方可扩展性；除增训练步数还有多方式扩展（大 batch、data reuse、采样更多 completion/prompt）。', '**Agentic RL**：单轮任务 vs agentic 系统（长时间推理、调工具、交互外部环境）。agentic rollout 含多轮生成和环境交互（tool calls、observations、rewards、状态变化）——需更复杂基础设施。设计模式：模块化工具/环境接口、mask 目标只含 agent 生成 token（非环境输出）、支持中间 process rewards 改进长轨迹 credit assignment、探索环境感知的 advantage 归一化、异步基础设施处理大幅变化完成时间、扩展环境编排支撑数千并发环境无中心瓶颈。'], 'fig_after': {'0': [{'src': 'fig08.png', 'caption': '图 8：RL scaling 或 agentic RL 示意。'}]}}, {'type': 'h2', 'title': '从策略梯度到前沿 RL：总结', 'paras': ['**策略梯度**：VPG 提供几乎所有算法的核心思想——增好动作概率、减坏动作，数学上 = log 概率梯度 × 学习信号。现代算法更复杂但都基于此结构。', '**REINFORCE 具体实例化 VPG**：对期望取 Monte Carlo（采样 rollout 平均）。高方差可用动作无关 baseline 降（RLOO 排除当前样本造 prompt 特定 baseline）。', '**PPO = 强大的优势估计 + 保守更新**：actor-critic 用学到值模型估计价值函数构造优势 + 重要性比和 clipping 允许多次更新而防破坏性更新。价值函数、重要性采样、优势估计、KL 发散在此汇聚。', '**GRPO 去 critic 简化 PPO**：免训值模型、采样多 completion 组内比较——更简单轻量的优化过程，牺牲采样 rollout 的计算换复杂度，因 reasoning 模型大规模 RL 训练而极流行。', '**Beyond vanilla GRPO**：DAPO、Dr.GRPO、GSPO、TIS、CISPO 不重造轮子，而是精修看似小的细节（loss 聚合方式、reward 归一化、batch 组成、clip 应用、per-token/per-sequence 比、引擎 mismatch 处理）——这些对 scale 重要。', '**Looking forward**：RL 仍充满关于数据、奖励、缩放、持续学习、长视界推理、agents 的开放问题。本文提供贡献这一前沿所需的概念基础。'], 'fig_after': {}}], 'conclusion': ['这篇是 LLM RL 完整指南：RL 基础（value/advantage、KL、重要性采样）→ 算法演化（VPG→REINFORCE→PPO→GRPO）→ GRPO 变体（GSPO/DAPO/Dr.GRPO/TIS/CISPO）→ 前沿（online/offline、continual、rubric、scaling、agentic）。', '核心：几乎所有 LLM RL 算法都是「log 概率梯度 × 学习信号」；PPO 训 critic 代价高、GRPO 去 critic 换多采样；scale 的成败在 loss 聚合、reward 归一化、clip 边界、引擎 mismatch 等细节。'], 'reference_url': 'https://cameronrwolfe.substack.com/p/llm-rl'}



with open("article_data.json", "w", encoding="utf-8") as f:
    json.dump(DATA, f, ensure_ascii=False, indent=1)
print(f"✅ 写入 article_data.json")